import { readFile } from 'node:fs/promises'
import { BaseSeeder } from '@adonisjs/lucid/seeders'
import type { QueryClientContract } from '@adonisjs/lucid/types/database'
import { LOCAL_LEVEL_TYPES, type LocalLevelType } from '#modules/logistics/domain/local_level_type'
import { parseCsv } from '#database/support/csv'

/*
 * The locations dataset of docs/04 §21.4: 7 provinces, 77 districts and 753
 * local levels from the committed `data/locations.csv`, upserted by `code`
 * (docs/04a §9.1–§9.3, docs/09 §8.8). The CSV is generated by
 * scripts/extract_locations.mjs from Nepal Post's and the Central Bureau of
 * Statistics' lists and never edited by hand; its header names the sources
 * [Verify-external VX-10]. adonisrc.ts copies it into the build, so the
 * release step finds it next to the compiled seeder.
 *
 * The whole dataset is checked before anything is written (T-SHOP-117), so
 * a wrong file fails the release step instead of seeding half a country.
 * A second run changes nothing (T-ARCH-018): a row is only rewritten when a
 * name, type or ward count differs. `is_active` is left alone on existing
 * rows, so a code retired by a reviewed migration stays retired (docs/04a §9
 * "Changes"). Never deletes.
 */

export const LOCATIONS_FILE = new URL('./data/locations.csv', import.meta.url)

export type LocationRow = {
  provinceCode: string
  provinceNameEn: string
  provinceNameNe: string
  districtCode: string
  districtNameEn: string
  districtNameNe: string
  code: string
  nameEn: string
  nameNe: string
  type: LocalLevelType
  wardCount: number
}

// docs/04 §21.4 [Verified-doc]; a boundary change updates these with the CSV.
const EXPECTED = {
  provinces: 7,
  districts: 77,
  localLevels: 753,
  wards: 6743,
  byType: { metropolitan: 6, sub_metropolitan: 11, municipality: 276, rural_municipality: 460 },
} as const satisfies { byType: Record<LocalLevelType, number> } & Record<string, unknown>

const COLUMNS = [
  'province_code',
  'province_name_en',
  'province_name_ne',
  'district_code',
  'district_name_en',
  'district_name_ne',
  'code',
  'name_en',
  'name_ne',
  'type',
  'ward_count',
] as const

// A local level's `name_en` is its place name followed by this label (docs/04 §21.4 step 3).
export const TYPE_LABELS: Record<LocalLevelType, string> = {
  metropolitan: 'Metropolitan City',
  sub_metropolitan: 'Sub-Metropolitan City',
  municipality: 'Municipality',
  rural_municipality: 'Rural Municipality',
}
// The longer label of each pair first: "Sub-Metropolitan City" ends with
// "Metropolitan City", and "Rural Municipality" with "Municipality".
const LABEL_ORDER: LocalLevelType[] = [
  'sub_metropolitan',
  'metropolitan',
  'rural_municipality',
  'municipality',
]

export class LocationsDatasetError extends Error {}

export async function readLocations(file: URL | string = LOCATIONS_FILE): Promise<LocationRow[]> {
  const records = parseCsv(await readFile(file, 'utf8'))
  const columns = Object.keys(records[0] ?? {})
  if (columns.join(',') !== COLUMNS.join(',')) {
    throw new LocationsDatasetError(`unexpected columns: ${columns.join(',')}`)
  }
  return records.map((record) => ({
    provinceCode: record.province_code,
    provinceNameEn: record.province_name_en,
    provinceNameNe: record.province_name_ne,
    districtCode: record.district_code,
    districtNameEn: record.district_name_en,
    districtNameNe: record.district_name_ne,
    code: record.code,
    nameEn: record.name_en,
    nameNe: record.name_ne,
    type: record.type as LocalLevelType,
    wardCount: /^\d+$/.test(record.ward_count) ? Number(record.ward_count) : Number.NaN,
  }))
}

const isCleanName = (name: string) =>
  name.length > 0 && name === name.trim() && name === name.normalize('NFC')

/**
 * Checks the dataset against docs/04 §21.4 and docs/04a §9.1–§9.3 and
 * returns its counts. Throws one LocationsDatasetError listing every problem.
 */
export function checkLocations(rows: LocationRow[]) {
  const problems: string[] = []
  const codes = new Set<string>()
  const englishNames = new Set<string>()
  const provinces = new Map<string, string>()
  const districts = new Map<string, string>()
  const byType: Record<string, number> = {}
  let wards = 0

  const sameName = (map: Map<string, string>, key: string, names: string, label: string) => {
    const known = map.get(key)
    if (known === undefined) map.set(key, names)
    else if (known !== names) problems.push(`${label} has two names`)
  }

  for (const row of rows) {
    if (codes.has(row.code)) problems.push(`${row.code} is listed twice`)
    codes.add(row.code)
    if (!/^[1-7]\d{4}$/.test(row.code)) problems.push(`"${row.code}" is not a local-level code`)
    if (row.code.slice(0, 3) !== row.districtCode) {
      problems.push(`${row.code} is not in district ${row.districtCode}`)
    }
    if (row.districtCode.slice(0, 1) !== row.provinceCode) {
      problems.push(`district ${row.districtCode} is not in province ${row.provinceCode}`)
    }
    if (!(LOCAL_LEVEL_TYPES as readonly string[]).includes(row.type)) {
      problems.push(`${row.code} has the unknown type "${row.type}"`)
    } else {
      byType[row.type] = (byType[row.type] ?? 0) + 1
      // The longest label decides, so "… Rural Municipality" is not a municipality.
      const labelled = LABEL_ORDER.find((type) => row.nameEn.endsWith(` ${TYPE_LABELS[type]}`))
      if (labelled !== row.type) {
        problems.push(`${row.code}: "${row.nameEn}" is not labelled "${TYPE_LABELS[row.type]}"`)
      }
    }
    if (!Number.isInteger(row.wardCount) || row.wardCount < 1 || row.wardCount > 40) {
      problems.push(`${row.code} has ${row.wardCount} wards, outside 1 to 40`)
    }
    wards += row.wardCount
    if (![row.nameEn, row.nameNe].every(isCleanName)) {
      problems.push(`${row.code} has a name that is empty, padded or not NFC`)
    }
    // A picker lists the local levels of one district by name, so two may not share one.
    const englishName = `${row.districtCode} ${row.nameEn.toLowerCase()}`
    if (englishNames.has(englishName)) {
      problems.push(
        `${row.code}: "${row.nameEn}" is already a local level of district ${row.districtCode}`
      )
    }
    englishNames.add(englishName)
    const districtNames = [row.districtNameEn, row.districtNameNe]
    const provinceNames = [row.provinceNameEn, row.provinceNameNe]
    if (![...districtNames, ...provinceNames].every(isCleanName)) {
      problems.push(`${row.code} has a district or province name that is empty, padded or not NFC`)
    }
    sameName(districts, row.districtCode, districtNames.join('|'), `district ${row.districtCode}`)
    sameName(provinces, row.provinceCode, provinceNames.join('|'), `province ${row.provinceCode}`)
  }

  const summary = {
    provinces: provinces.size,
    districts: districts.size,
    localLevels: rows.length,
    wards,
    byType: Object.fromEntries(LOCAL_LEVEL_TYPES.map((type) => [type, byType[type] ?? 0])),
  }
  if (summary.provinces !== EXPECTED.provinces) {
    problems.push(`${summary.provinces} provinces, expected ${EXPECTED.provinces}`)
  }
  if (summary.districts !== EXPECTED.districts) {
    problems.push(`${summary.districts} districts, expected ${EXPECTED.districts}`)
  }
  if (summary.localLevels !== EXPECTED.localLevels) {
    problems.push(`${summary.localLevels} local levels, expected ${EXPECTED.localLevels}`)
  }
  if (summary.wards !== EXPECTED.wards) {
    problems.push(`${summary.wards} wards, expected ${EXPECTED.wards}`)
  }
  for (const type of LOCAL_LEVEL_TYPES) {
    if (summary.byType[type] !== EXPECTED.byType[type]) {
      problems.push(`${summary.byType[type]} of type ${type}, expected ${EXPECTED.byType[type]}`)
    }
  }
  if (problems.length > 0) {
    throw new LocationsDatasetError(`locations dataset refused:\n${problems.join('\n')}`)
  }
  return summary
}

/** Checks the dataset, then upserts it in one transaction (a savepoint inside one). */
export async function seedLocations(client: QueryClientContract, rows: LocationRow[]) {
  checkLocations(rows)
  const unique = <T>(items: T[], key: (item: T) => string) => [
    ...new Map(items.map((item) => [key(item), item])).values(),
  ]
  const provinces = unique(rows, (row) => row.provinceCode).map((row) => ({
    code: row.provinceCode,
    name_en: row.provinceNameEn,
    name_ne: row.provinceNameNe,
  }))
  const districts = unique(rows, (row) => row.districtCode).map((row) => ({
    code: row.districtCode,
    province_code: row.provinceCode,
    name_en: row.districtNameEn,
    name_ne: row.districtNameNe,
  }))
  const localLevels = rows.map((row) => ({
    code: row.code,
    district_code: row.districtCode,
    name_en: row.nameEn,
    name_ne: row.nameNe,
    type: row.type,
    ward_count: row.wardCount,
  }))

  // One statement per table: the rows travel as one jsonb parameter.
  await client.transaction(async (trx) => {
    await trx.rawQuery(
      `INSERT INTO provinces (code, name_en, name_ne)
       SELECT code, name_en, name_ne
         FROM jsonb_to_recordset(?::jsonb) AS r(code text, name_en text, name_ne text)
       ON CONFLICT (code) DO UPDATE
          SET name_en = EXCLUDED.name_en, name_ne = EXCLUDED.name_ne
        WHERE (provinces.name_en, provinces.name_ne)
              IS DISTINCT FROM (EXCLUDED.name_en, EXCLUDED.name_ne)`,
      [JSON.stringify(provinces)]
    )
    await trx.rawQuery(
      `INSERT INTO districts (code, province_code, name_en, name_ne)
       SELECT code, province_code, name_en, name_ne
         FROM jsonb_to_recordset(?::jsonb)
           AS r(code text, province_code text, name_en text, name_ne text)
       ON CONFLICT (code) DO UPDATE
          SET name_en = EXCLUDED.name_en, name_ne = EXCLUDED.name_ne
        WHERE (districts.name_en, districts.name_ne)
              IS DISTINCT FROM (EXCLUDED.name_en, EXCLUDED.name_ne)`,
      [JSON.stringify(districts)]
    )
    await trx.rawQuery(
      `INSERT INTO local_levels (code, district_code, name_en, name_ne, type, ward_count)
       SELECT code, district_code, name_en, name_ne, type, ward_count
         FROM jsonb_to_recordset(?::jsonb)
           AS r(code text, district_code text, name_en text, name_ne text, type text,
                ward_count smallint)
       ON CONFLICT (code) DO UPDATE
          SET name_en = EXCLUDED.name_en, name_ne = EXCLUDED.name_ne,
              type = EXCLUDED.type, ward_count = EXCLUDED.ward_count
        WHERE (local_levels.name_en, local_levels.name_ne, local_levels.type, local_levels.ward_count)
              IS DISTINCT FROM (EXCLUDED.name_en, EXCLUDED.name_ne, EXCLUDED.type, EXCLUDED.ward_count)`,
      [JSON.stringify(localLevels)]
    )
  })
}

export default class LocationsSeeder extends BaseSeeder {
  async run() {
    await seedLocations(this.client, await readLocations())
  }
}
